import * as React from "react";

export interface TreeNode<T = unknown> {
  id: string;
  label: string;
  icon?: React.ElementType;
  children?: TreeNode<T>[];
  data?: T;
  disabled?: boolean;
  defaultExpanded?: boolean;
}

export interface TreeConfig {
  multiSelect?: boolean;
  showLines?: boolean;
  defaultExpandAll?: boolean;
  defaultExpanded?: string[];
  defaultSelected?: string[];
}

export interface TreeContextValue<T = unknown> {
  nodes: TreeNode<T>[];
  expanded: Set<string>;
  selected: Set<string>;
  focused: string | null;
  config: TreeConfig;
  expand: (id: string) => void;
  collapse: (id: string) => void;
  toggleExpand: (id: string) => void;
  select: (id: string, additive?: boolean) => void;
  focus: (id: string | null) => void;
  expandAll: () => void;
  collapseAll: () => void;
  expandTo: (id: string) => void;
}

import * as React from "react";
import type { TreeContextValue } from "./tree-types";

export const TreeCtx = React.createContext<TreeContextValue | null>(null);

export function useTree<T = unknown>(): TreeContextValue<T> {
  const ctx = React.useContext(TreeCtx);
  if (!ctx) throw new Error("useTree must be used inside TreeRoot");
  return ctx as TreeContextValue<T>;
}

import type { TreeNode } from "./tree-types";

/** Returns all node ids in the tree */
export function getAllIds(nodes: TreeNode[]): string[] {
  return nodes.flatMap((n) => [
    n.id,
    ...(n.children ? getAllIds(n.children) : []),
  ]);
}

/** Returns flat list of visible node ids (respecting collapsed state) */
export function getVisibleIds(
  nodes: TreeNode[],
  expanded: Set<string>,
): string[] {
  const result: string[] = [];
  function walk(ns: TreeNode[]) {
    for (const n of ns) {
      result.push(n.id);
      if (n.children?.length && expanded.has(n.id)) walk(n.children);
    }
  }
  walk(nodes);
  return result;
}

/** Find a node by id */
export function findNode(nodes: TreeNode[], id: string): TreeNode | null {
  for (const n of nodes) {
    if (n.id === id) return n;
    if (n.children) {
      const found = findNode(n.children, id);
      if (found) return found;
    }
  }
  return null;
}

/** Get all ancestor ids of a node */
export function getAncestorIds(
  nodes: TreeNode[],
  targetId: string,
  path: string[] = [],
): string[] | null {
  for (const n of nodes) {
    if (n.id === targetId) return path;
    if (n.children) {
      const found = getAncestorIds(n.children, targetId, [...path, n.id]);
      if (found) return found;
    }
  }
  return null;
}

/** Get parent id */
export function getParentId(
  nodes: TreeNode[],
  id: string,
  parent: string | null = null,
): string | null {
  for (const n of nodes) {
    if (n.id === id) return parent;
    if (n.children) {
      const found = getParentId(n.children, id, n.id);
      if (found !== null) return found;
    }
  }
  return null;
}

/** Get first child id */
export function getFirstChildId(nodes: TreeNode[], id: string): string | null {
  const node = findNode(nodes, id);
  return node?.children?.[0]?.id ?? null;
}

import * as React from "react";
import { TreeCtx } from "./tree-context";
import { TreeNode as TreeNodeComponent } from "./tree-node";
import {
  getAllIds,
  getVisibleIds,
  getAncestorIds,
  getParentId,
  getFirstChildId,
} from "./tree-utils";
import { cn } from "@/lib/utils";
import type { TreeNode, TreeConfig, TreeContextValue } from "./tree-types";

export interface TreeRootProps<T = unknown> {
  nodes: TreeNode<T>[];
  config?: TreeConfig;
  onSelect?: (ids: string[], nodes: TreeNode<T>[]) => void;
  className?: string;
}

export function TreeRoot<T = unknown>({
  nodes,
  config = {},
  onSelect,
  className,
}: TreeRootProps<T>) {
  const allIds = React.useMemo(() => getAllIds(nodes), [nodes]);

  const [expanded, setExpanded] = React.useState<Set<string>>(() => {
    if (config.defaultExpandAll) return new Set(allIds);
    const ids = new Set<string>(config.defaultExpanded ?? []);
    function addDefaults(ns: TreeNode<T>[]) {
      for (const n of ns) {
        if (n.defaultExpanded) ids.add(n.id);
        if (n.children) addDefaults(n.children);
      }
    }
    addDefaults(nodes);
    return ids;
  });

  const [selected, setSelected] = React.useState<Set<string>>(
    new Set(config.defaultSelected ?? []),
  );
  const [focused, setFocused] = React.useState<string | null>(null);
  const containerRef = React.useRef<HTMLDivElement>(null);

  function handleKeyDown(e: React.KeyboardEvent) {
    if (!focused) return;
    const visible = getVisibleIds(nodes, expanded);
    const idx = visible.indexOf(focused);

    switch (e.key) {
      case "ArrowDown": {
        e.preventDefault();
        const next = visible[idx + 1];
        if (next) setFocused(next);
        break;
      }
      case "ArrowUp": {
        e.preventDefault();
        const prev = visible[idx - 1];
        if (prev) setFocused(prev);
        break;
      }
      case "ArrowRight": {
        e.preventDefault();
        if (expanded.has(focused)) {
          const child = getFirstChildId(nodes, focused);
          if (child) setFocused(child);
        } else {
          const node = visible.find((id) => id === focused);
          if (node) expand(focused);
        }
        break;
      }
      case "ArrowLeft": {
        e.preventDefault();
        if (expanded.has(focused)) {
          collapse(focused);
        } else {
          const parent = getParentId(nodes as TreeNode[], focused);
          if (parent) setFocused(parent);
        }
        break;
      }
      case "Enter":
      case " ": {
        e.preventDefault();
        select(focused, e.shiftKey || e.metaKey || e.ctrlKey);
        break;
      }
      case "Home": {
        e.preventDefault();
        setFocused(visible[0] ?? null);
        break;
      }
      case "End": {
        e.preventDefault();
        setFocused(visible[visible.length - 1] ?? null);
        break;
      }
    }
  }

  function expand(id: string) {
    setExpanded((p) => new Set([...p, id]));
  }
  function collapse(id: string) {
    setExpanded((p) => {
      const n = new Set(p);
      n.delete(id);
      return n;
    });
  }
  function toggleExpand(id: string) {
    expanded.has(id) ? collapse(id) : expand(id);
  }
  function expandAll() {
    setExpanded(new Set(allIds));
  }
  function collapseAll() {
    setExpanded(new Set());
  }

  function expandTo(id: string) {
    const ancestors = getAncestorIds(nodes as TreeNode[], id) ?? [];
    setExpanded((p) => new Set([...p, ...ancestors]));
  }

  function select(id: string, additive = false) {
    let next: Set<string>;
    if (additive && config.multiSelect) {
      next = new Set(selected);
      selected.has(id) ? next.delete(id) : next.add(id);
    } else {
      next = new Set([id]);
    }
    setSelected(next);
    onSelect?.(
      [...next],
      [...next].map((nid) => {
        const n = getAllIds(nodes);
        return { id: nid, label: nid } as TreeNode<T>;
      }),
    );
  }

  const ctx: TreeContextValue<T> = {
    nodes: nodes as TreeNode<T>[],
    expanded,
    selected,
    focused,
    config,
    expand,
    collapse,
    toggleExpand,
    select,
    focus: setFocused,
    expandAll,
    collapseAll,
    expandTo,
  };

  return (
    <TreeCtx.Provider value={ctx as TreeContextValue}>
      <div
        ref={containerRef}
        role="tree"
        tabIndex={0}
        onKeyDown={handleKeyDown}
        onFocus={() => {
          if (!focused && nodes[0]) setFocused(nodes[0].id);
        }}
        className={cn("outline-none select-none", className)}
      >
        {nodes.map((node, i) => (
          <TreeNodeComponent
            key={node.id}
            node={node as TreeNode}
            depth={0}
            isLast={i === nodes.length - 1}
          />
        ))}
      </div>
    </TreeCtx.Provider>
  );
}

TreeRoot.displayName = "TreeRoot";

import * as React from "react";
import { motion, AnimatePresence } from "motion/react";
import { useTree } from "./tree-context";
import { IconChevronRight, IconFile } from "@tabler/icons-react";
import { cn } from "@/lib/utils";
import type { TreeNode } from "./tree-types";

const INDENT = 16;

export function TreeNode({
  node,
  depth,
  isLast,
}: {
  node: TreeNode;
  depth: number;
  isLast: boolean;
}) {
  const { expanded, selected, focused, toggleExpand, select, focus, config } =
    useTree();

  const isExpanded = expanded.has(node.id);
  const isSelected = selected.has(node.id);
  const isFocused = focused === node.id;
  const hasChildren = !!node.children?.length;
  const Icon = node.icon ?? (hasChildren ? null : IconFile);

  function handleClick(e: React.MouseEvent) {
    if (node.disabled) return;
    focus(node.id);
    select(node.id, e.metaKey || e.ctrlKey || e.shiftKey);
    if (hasChildren) toggleExpand(node.id);
  }

  function handleChevron(e: React.MouseEvent) {
    e.stopPropagation();
    toggleExpand(node.id);
  }

  return (
    <div>
      <div
        role="treeitem"
        aria-expanded={hasChildren ? isExpanded : undefined}
        aria-selected={isSelected}
        aria-disabled={node.disabled}
        onClick={handleClick}
        style={{ paddingLeft: depth * INDENT }}
        className={cn(
          "flex items-center gap-1.5 py-[3px] pr-3 rounded-sm cursor-pointer transition-colors group relative",
          isSelected && "bg-primary/10",
          isFocused && !isSelected && "bg-muted/50",
          !isSelected && !isFocused && "hover:bg-muted/40",
          node.disabled && "opacity-40 cursor-not-allowed",
        )}
      >
        {config.showLines && depth > 0 && (
          <span
            className="absolute left-0 top-0 bottom-0 border-l border-border/30"
            style={{ left: (depth - 1) * INDENT + 8 }}
          />
        )}

        <span className="w-4 h-4 flex items-center justify-center shrink-0">
          {hasChildren ? (
            <button
              type="button"
              onClick={handleChevron}
              className="w-4 h-4 flex items-center justify-center"
            >
              <IconChevronRight
                size={12}
                strokeWidth={2}
                className={cn(
                  "text-muted-foreground/40 transition-transform",
                  isExpanded && "rotate-90",
                )}
              />
            </button>
          ) : null}
        </span>

        {Icon && (
          <Icon
            size={14}
            strokeWidth={1.8}
            className={cn(
              "shrink-0 transition-colors",
              isSelected ? "text-primary/70" : "text-muted-foreground/50",
            )}
          />
        )}

        <span
          className={cn(
            "text-[13px] truncate flex-1 transition-colors",
            isSelected
              ? "text-primary font-medium"
              : isFocused
                ? "text-foreground"
                : "text-foreground/80",
          )}
        >
          {node.label}
        </span>
      </div>

      <AnimatePresence initial={false}>
        {hasChildren && isExpanded && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.15, ease: "easeInOut" }}
            className=" space-y-0.5"
          >
            {node.children!.map((child, i) => (
              <TreeNode
                key={child.id}
                node={child}
                depth={depth + 1}
                isLast={i === node.children!.length - 1}
              />
            ))}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

TreeNode.displayName = "TreeNode";

export { TreeRoot } from "./tree-root";
export { TreeNode } from "./tree-node";
export { useTree } from "./tree-context";
export type {
  TreeNode as TreeNodeType,
  TreeConfig,
  TreeContextValue,
} from "./tree-types";
